import * as fs from 'node:fs/promises';
import {spawn,spawnSync} from 'node:child_process';
import {once} from 'node:events';
import {mock} from 'node:test';
import {fileURLToPath} from 'node:url';
const base='/tmp/codex-tool-runs/svton/m2-r2-generation-review-20260930';
const modulePath='/Users/zhaoxingbo/Workspace/ai-driven/svton/shipkit/dist/shared/file-lock.js';
const [mode,file]=process.argv.slice(2);
if(mode==='cleaner'){
 const {default:ignored,...named}=fs;
 mock.module('node:fs/promises',{namedExports:{...named,rename:async(from,to)=>{
  await fs.rename(from,to);
  if(from===file+'.lock.prev/owner'){
   process.send({event:'owner-moved',path:to});
   await new Promise(()=>{});
  }
 }}});
 const {withFileLock}=await import(modulePath);
 await withFileLock(file,()=>{}, {timeoutMs:2000});
 process.exit(3);
}else if(mode==='waiter'){
 const {withFileLock}=await import(modulePath);
 const start=Date.now();process.send({event:'waiter-started'});
 try{await withFileLock(file,()=>{process.send({event:'entered'})},{timeoutMs:150});process.send({event:'finished',elapsedMs:Date.now()-start});}
 catch(e){process.send({event:'rejected',message:e.message,elapsedMs:Date.now()-start});}
 process.exit(0);
}else{
 const dir=await fs.mkdtemp(base+'/crash-'),state=dir+'/state.json',prev=state+'.lock.prev';
 const dead=spawnSync(process.execPath,['-e','process.exit(0)']);
 try{process.kill(dead.pid,0);throw Error('fixture PID reused')}catch(e){if(e.code!=='ESRCH')throw e;}
 await fs.writeFile(state+'.lock',`${dead.pid}\tdead-holder-token\n`);
 await fs.mkdir(prev);await fs.writeFile(prev+'/owner',`${dead.pid}\tdead-reaper-token\tdead-holder-token\n`);
 const launch=(role)=>spawn(process.execPath,['--experimental-test-module-mocks',fileURLToPath(import.meta.url),role,state],{stdio:['ignore','ignore','inherit','ipc']});
 const cleaner=launch('cleaner');const [moved]=await once(cleaner,'message');
 if(moved.event!=='owner-moved')throw Error('unexpected event');
 const cleanerExit=once(cleaner,'exit');cleaner.kill('SIGKILL');await cleanerExit;
 const residue=await fs.readdir(prev);
 await new Promise(r=>setTimeout(r,650)); // let directory exceed residue threshold before waiter starts
 const waiter=launch('waiter');const events=[];let exited=false;
 waiter.on('message',m=>events.push(m));const waiterExit=once(waiter,'exit').then(x=>{exited=true;return x});
 await once(waiter,'message');const observedStart=Date.now();
 await new Promise(r=>setTimeout(r,1200));
 const exitedBeforeWatchdog=exited;
 if(!exited)waiter.kill('SIGKILL');await waiterExit;
 const result={cleanerKilledAfterRealRename:true,requestedTimeoutMs:150,observedMs:Date.now()-observedStart,exitedBeforeWatchdog,events,residueAfterCrash:residue,residueAfterWait:await fs.readdir(prev),onlyCleanerSchedulingMocked:true,waiterUsesUnmockedImplementation:true};
 await fs.writeFile(base+'/crash-result.json',JSON.stringify(result,null,2));console.log(JSON.stringify(result));
}
